int parse_nested_tokens(const char *str, int max_depth) {
    if (!str || max_depth <= 0) return -1;
    int depth = 0;
    int max_seen = 0;
    for (size_t i = 0; str[i] != '\0'; ++i) {
        if (str[i] == '(') {
            depth++;
